<script setup>
import SearchSelect from "../components/SearchSelect.vue";
import { useExpenseOptions } from "../composables/useExpenseOptions";
const expenseChoices = useExpenseOptions();
import AppIcon from "../components/AppIcon.vue";
import { paymentColumns, numericColumns } from "../lib/expense-columns";
import { computed, ref, onBeforeUnmount } from 'vue';
import { paymentStore,savePayments } from '../lib/payment-store';
import { parsePaymentWorkbook,paymentDuplicate,paymentEvidenceCandidate,allocationKind,allocationIssue } from '../lib/payment-records';
import { saveLedgerAttachment,getLedgerAttachment } from '../lib/ledger-attachments';
import { directory,suggestAllocation } from '../lib/expense-directory';
const query=ref('');
const message=ref(''),busy=ref(false),onlyMissing=ref(false),editing=ref(null),preview=ref(''),candidates=ref([]),period=ref('');
const missing=computed(()=>paymentStore.rows.filter(r=>!r.evidenceConfirmed&&!r.duplicateOf).length);
const rows=computed(()=>paymentStore.rows.filter(r=>(!onlyMissing.value||!r.evidenceConfirmed&&!r.duplicateOf)&&(!query.value||[r.seller,r.payer,r.project,r.purpose,r.buyer].join(' ').includes(query.value))));
const tableRows=computed(()=>rows.value.flatMap(r=>(r.lines?.length?r.lines:[{}]).map((line,i)=>({...r,...line,total:i===0?r.total:'',refund:i===0?r.refund:'',record:r,rowKey:r.id+'|'+i}))));
const money=v=>v===''||v==null?'—':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const fields=[['date','下单日期'],['payer','付款名称'],['seller','收款名称'],['total','实付合计'],['refund','退回金额'],['buyer','归属公司'],['project','使用项目'],['team','使用班组/单位'],['deliveryNumber','送货单编号'],['note','备注'],['reimbursementPeriod','报销期间']];
function close(){editing.value=null;candidates.value=[];if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';}
onBeforeUnmount(close);
async function open(r){close();editing.value={...r,lines:(r.lines||[]).map(l=>({...l})),allocation:allocationKind(r)};try{const f=await getLedgerAttachment('payment:'+r.id);if(f)preview.value=URL.createObjectURL(f.blob);}catch(e){message.value=e.message;}}
async function hash(file){const b=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());return Array.from(new Uint8Array(b),n=>n.toString(16).padStart(2,'0')).join('');}
let importedImages=[];
async function importFiles(e){busy.value=true;message.value='';try{const files=Array.from(e.target.files||[]);e.target.value='';importedImages=files.filter(f=>/\.(png|jpe?g|webp|bmp)$/i.test(f.name));let next=paymentStore.rows.slice(),added=0,repeat=0;for(const f of files.filter(f=>/\.xlsx?$/i.test(f.name)&&!f.name.startsWith('~$'))){for(const r of parsePaymentWorkbook(await f.arrayBuffer(),f.name)){if(next.some(x=>x.id===r.id)){repeat++;continue;}r.reimbursementPeriod=period.value;next.push(r);added++;}}savePayments(next);if(editing.value)close();message.value='导入 '+added+' 笔待核对付款，同一来源已存在 '+repeat+' 笔；读取 '+importedImages.length+' 张截图。请逐笔核对截图后保存，未核对的持续提醒。';}catch(err){message.value=err.message;}finally{busy.value=false;}}
function findImages(){candidates.value=importedImages.filter(f=>paymentEvidenceCandidate(editing.value,f.name));message.value=candidates.value.length?'找到 '+candidates.value.length+' 张日期、金额相符的截图，请选择并对照收款方。':'未找到日期和金额相符的截图，请手动补充。';}
async function attach(file){if(!file)return;if(!file.type.startsWith('image/')){message.value='请上传图片格式的付款截图';return;}try{const digest=await hash(file);const draft={...editing.value,evidenceHash:digest};const dup=paymentStore.rows.find(r=>r.id!==draft.id&&paymentDuplicate(r,draft));if(dup){savePayments(paymentStore.rows.map(r=>r.id===draft.id?{...r,duplicateOf:dup.id}:r));editing.value.duplicateOf=dup.id;message.value='重复付款：日期、金额和截图内容均与 '+dup.source+' 一致，已标记为重复，不计入费用。';return;}await saveLedgerAttachment('payment:'+draft.id,file);editing.value={...draft,duplicateOf:'',evidenceName:file.name,evidenceConfirmed:false};if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(file);const next=paymentStore.rows.map(r=>r.id===draft.id?{...r,duplicateOf:'',evidenceHash:digest,evidenceName:file.name,evidenceConfirmed:false}:r);savePayments(next);}catch(e){message.value=e.message;}}
function save(){const d=editing.value;d.purpose=(d.lines||[]).map(l=>l.purpose).filter(Boolean).join(' / ')||d.purpose;if(!d.date||!d.seller||d.total===''||!Number.isFinite(Number(d.total))){message.value='请补全日期、收款方和有效金额';return;}if(d.reimbursement==='已报销'&&(!d.evidenceHash||!d.evidenceConfirmed||!d.buyer||allocationIssue(d)||!d.reimbursementPeriod)){message.value='标记已报销前请确认截图、归属公司、费用归属及报销期间';return;}if(paymentStore.rows.some(r=>r.id!==d.id&&paymentDuplicate(r,d))){message.value='日期、金额和截图均重复，请核对，未保存';return;}try{savePayments(paymentStore.rows.map(r=>r.id===d.id?{...d}:r));close();message.value='已保存；缺少或未确认截图的付款继续提醒';}catch(e){message.value=e.message;}}
function suggest(){const r=suggestAllocation(editing.value.seller,editing.value.buyer);if(r){editing.value.buyer=r.buyer;editing.value.project=r.project;editing.value.allocation='指定工地';editing.value.evidenceConfirmed=false;}else message.value='未配置唯一对应关系，请手动选择公司与工地';}
</script><template>
<section class="expense-screen">
<header class="expense-heading"><div><div class="eyebrow">费用管理</div><h1>付款凭证</h1></div><div class="heading-counts"><span class="soft-badge">{{ paymentStore.rows.length }} 笔付款</span><span class="status-pill warning" v-if="missing">{{ missing }} 笔待补凭证</span></div></header>
<section class="finance-card">
  <div class="finance-toolbar"><label class="toolbar-field">报销期间<input v-model="period" placeholder="如：2026年第三季度" /></label><div class="toolbar-actions"><label class="btn-primary file-button" :class="{disabled:busy}"><AppIcon name="upload" :size="17" />{{ busy?'正在读取…':'导入清单 / 图片' }}<input type="file" multiple accept=".xlsx,.xls,.png,.jpg,.jpeg" :disabled="busy" @change="importFiles" /></label><label class="btn file-button" :class="{disabled:busy}"><AppIcon name="folder" :size="17" />导入文件夹<input type="file" webkitdirectory multiple :disabled="busy" @change="importFiles" /></label></div></div>
  <p v-if="message && !editing" role="status" class="finance-notice">{{ message }}</p>
  <div class="finance-filterbar"><input v-model="query" type="search" placeholder="搜索收款方、项目或费用" aria-label="搜索付款记录" /><label class="inline-check"><input v-model="onlyMissing" type="checkbox" />仅看待补凭证 <span class="count-dot">{{ missing }}</span></label><span class="table-count">{{ rows.length }} 笔 · {{ tableRows.length }} 行明细</span></div>
  <div class="finance-table-wrap payment-list"><table class="finance-table"><thead><tr><th class="sticky-action">操作</th><th v-for="[key,label] in paymentColumns" :key="key" :class="{'number-cell':numericColumns.includes(key)}">{{ label }}</th><th>凭证</th><th>报销状态</th></tr></thead><tbody><tr v-for="r in tableRows" :key="r.rowKey"><td class="sticky-action"><button class="text-action" @click="open(r.record)"><AppIcon name="edit" :size="14" />核对 / 编辑</button></td><td v-for="[key] in paymentColumns" :key="key" :class="{'number-cell':numericColumns.includes(key)}">{{ numericColumns.includes(key)?money(r[key]):r[key]||'—' }}</td><td><span class="status-pill" :class="r.evidenceConfirmed?'success':'warning'">{{ r.duplicateOf?'重复记录':r.evidenceConfirmed?'已核对':r.evidenceHash?'待核对':'缺少截图' }}</span></td><td><span class="status-pill" :class="r.reimbursement==='已报销'?'success':'neutral'">{{ r.reimbursement }}</span></td></tr><tr v-if="!tableRows.length"><td colspan="17"><div class="finance-empty"><AppIcon name="payment" :size="34" /><strong>{{ paymentStore.rows.length?'没有匹配的付款':'暂无付款记录' }}</strong><span>{{ paymentStore.rows.length?'调整搜索或筛选条件':'导入付款清单，开始核对凭证' }}</span></div></td></tr></tbody></table></div>
</section>
<div v-if="editing" class="payment-overlay" role="dialog" aria-modal="true" aria-labelledby="payment-dialog-title" @keydown.esc="close"><section class="payment-dialog"><header class="finance-dialog-heading"><div><h2 id="payment-dialog-title">付款核对</h2><span>{{ editing.date }} · {{ editing.seller }}</span></div><button class="icon-button" aria-label="关闭付款核对" @click="close"><AppIcon name="close" /></button></header><div class="payment-columns"><section class="payment-evidence"><div class="evidence-toolbar"><h3>付款截图</h3><label class="btn file-button"><AppIcon name="upload" :size="15" />{{ preview?'更换截图':'补充截图' }}<input type="file" accept="image/*" @change="attach($event.target.files?.[0])" /></label><button class="btn" @click="findImages">匹配截图</button></div><div class="evidence-canvas"><img v-if="preview" :src="preview" alt="付款截图" /><div v-else class="finance-empty"><AppIcon name="payment" :size="38" /><strong>尚未关联截图</strong><span>补充截图后完成核对</span></div></div><div v-if="candidates.length" class="evidence-candidates"><button v-for="f in candidates" :key="f.name" class="btn" @click="attach(f)">{{ f.name }}</button></div></section><section class="payment-form"><h3>付款信息</h3><div class="form-grid"><label v-for="[k,label] in fields" :key="k">{{ label }}<SearchSelect v-if="expenseChoices[k]" v-model="editing[k]" :options="expenseChoices[k]" :label="label" @update:model-value="editing.evidenceConfirmed=false" /><input v-else v-model="editing[k]" :type="k==='date'?'date':'text'" :list="k==='buyer'?'payment-buyers':k==='project'?'payment-projects':undefined" @input="editing.evidenceConfirmed=false" /></label></div><datalist id="payment-buyers"><option v-for="b in directory.buyers" :key="b">{{ b }}</option></datalist><datalist id="payment-projects"><option v-for="p in directory.projects" :key="p">{{ p }}</option></datalist><div class="form-grid"><label>费用归属<select v-model="editing.allocation"><option>指定工地</option><option>加油</option><option>个人报账</option><option>待确认</option></select></label><label>报销状态<select v-model="editing.reimbursement"><option>未核对</option><option>未报销</option><option>已报销</option></select></label></div><button class="text-action" @click="suggest"><AppIcon name="link" :size="15" />使用厂家对应关系</button><p v-if="allocationIssue(editing)" class="field-hint">{{ editing.allocation==='待确认'?'费用归属待确认':allocationIssue(editing) }}</p><h3>材料 / 费用明细</h3><div class="line-edit-list"><div v-for="(line,i) in editing.lines" :key="i" class="line-edit-item"><label class="line-title">材料或费用名称<input v-model="line.purpose" @input="editing.evidenceConfirmed=false" /></label><div class="form-grid"><label v-for="[key,label] in [['unit','单位'],['quantity','数量'],['unitPrice','单价'],['lineAmount','金额（元）']]" :key="key">{{ label }}<input v-model="line[key]" @input="editing.evidenceConfirmed=false" /></label></div></div></div><label class="inline-check review-confirm"><input v-model="editing.evidenceConfirmed" type="checkbox" :disabled="!editing.evidenceHash" />已核对截图的日期、金额和收款方</label><p v-if="message" role="alert" class="finance-notice">{{ message }}</p></section></div><footer class="finance-dialog-footer"><span :class="editing.evidenceConfirmed?'status-pill success':'status-pill warning'">{{ editing.evidenceConfirmed?'凭证已确认':'凭证待补全 / 核对' }}</span><button class="btn" @click="close">取消</button><button class="btn-primary" @click="save"><AppIcon name="check" :size="16" />保存核对结果</button></footer></section></div>
</section></template>
